{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Viqualine, the closest structural analogue, showed 80% absolute oral bioavailability in healthy subjects after a 25 mg tablet versus intravenous dosing; it shares the vinyl-substituted chiral amine and 6-methoxyquinoline core with the query, strongly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Alizapride, a basic methoxy-substituted heteroaromatic amine, had 72.5% absolute oral bioavailability in subjects, providing additional supportive evidence that ionizable basic heteroaromatic drugs of this type can achieve high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Tegaserod, a methoxyindole basic amidine, had only about 10% absolute bioavailability under fasted conditions; however, its structural transferability to the query is low because it lacks the vinyl-bicyclic amine and quinoline scaffold, so this low-F evidence is weak and does not override the closer viqualine data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue viqualine has high absolute oral bioavailability (73-80%) in humans and shares key structural features with the query, including the vinyl-substituted basic amine and 6-methoxyquinoline. Other high-F basic heteroaromatic drugs support this direction, while low-F analogues such as tegaserod are structurally distant and weakly transferable. The physicochemical prior also favors high bioavailability, though strong basicity and lack of direct query data introduce moderate uncertainty.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "Viqualine lacks the query's extra ring and hydroxyl group, so the effect of these modifications on absorption and first-pass metabolism is uncertain.",
    "Fasted-state bioavailability data for viqualine were not explicitly reported, while the query is assessed under fasted conditions.",
    "Metabolism, efflux, and solubility data for the query are not available experimentally."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

